const menuToggle = document.getElementById("menuToggle");
const primaryNav = document.getElementById("primaryNav");
const callbackModal = document.getElementById("popupModel");
const callbackForm = document.getElementById("form");
const callbackStatus = document.getElementById("callbackStatus");
const fullNameInput = document.getElementById("fullName");
const solutionFilters = document.querySelector(".solution-filters");
const solutionCards = document.querySelectorAll(".solution-card");
const filterStatus = document.getElementById("filterStatus");
const backgroundElements = document.querySelectorAll(".skip-link, .utility-bar, header, main, footer, .floating-whatsapp");
let lastFocusedElement = null;

document.getElementById("currentYear").textContent = String(new Date().getFullYear());

menuToggle.addEventListener("click", toggleNavigation);
primaryNav.addEventListener("click", function (event) {
    if (event.target.closest("a")) {
        closeNavigation();
    }
});
document.querySelectorAll("[data-open-callback]").forEach(function (button) {
    button.addEventListener("click", openCallbackModal);
});
callbackModal.querySelector(".close").addEventListener("click", closeCallbackModal);
callbackModal.addEventListener("click", function (event) {
    if (event.target === callbackModal) {
        closeCallbackModal();
    }
});
callbackForm.addEventListener("submit", onSubmitContactDetail);
document.addEventListener("keydown", handleGlobalKeydown);
solutionFilters.hidden = false;
solutionFilters.addEventListener("click", filterSolutions);

/**
 * Filters the local solution cards and announces the result without moving keyboard focus.
 * @param {MouseEvent} event The filter button activation.
 */
function filterSolutions(event) {
    const button = event.target.closest("[data-filter]");
    if (!button) {
        return;
    }

    const industry = button.dataset.filter;
    let visibleCount = 0;
    solutionCards.forEach(function (card) {
        card.hidden = industry !== "all" && card.dataset.industry !== industry;
        if (!card.hidden) {
            visibleCount += 1;
        }
    });
    solutionFilters.querySelectorAll("[data-filter]").forEach(function (filter) {
        filter.setAttribute("aria-pressed", String(filter === button));
    });
    filterStatus.textContent = `${visibleCount} ${visibleCount === 1 ? "solution" : "solutions"} shown.`;
}

/**
 * Toggles the compact navigation and synchronizes its accessible expanded state.
 */
function toggleNavigation() {
    const isOpen = menuToggle.getAttribute("aria-expanded") === "true";
    menuToggle.setAttribute("aria-expanded", String(!isOpen));
    menuToggle.setAttribute("aria-label", isOpen ? "Open navigation" : "Close navigation");
    primaryNav.classList.toggle("is-open", !isOpen);
}

/**
 * Closes the compact navigation after a link has been selected.
 */
function closeNavigation() {
    menuToggle.setAttribute("aria-expanded", "false");
    menuToggle.setAttribute("aria-label", "Open navigation");
    primaryNav.classList.remove("is-open");
}

/**
 * Opens the contact dialog, locks page scrolling, and moves focus into the form.
 * @param {Event} event The control activation event.
 */
function openCallbackModal(event) {
    lastFocusedElement = primaryNav.contains(event.currentTarget) && menuToggle.offsetParent !== null
        ? menuToggle
        : event.currentTarget;
    closeNavigation();
    if (event.currentTarget.dataset.contactIntent === "demo") {
        const messageInput = callbackForm.elements.message;
        if (!messageInput.value.trim()) {
            messageInput.value = "I would like to request a demo. Please contact me to discuss a suitable time.";
        }
    }
    callbackModal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    backgroundElements.forEach(function (element) {
        element.inert = true;
    });
    fullNameInput.focus();
}

/**
 * Closes the contact dialog and returns focus to the control that opened it.
 */
function closeCallbackModal() {
    callbackModal.setAttribute("aria-hidden", "true");
    document.body.classList.remove("modal-open");
    backgroundElements.forEach(function (element) {
        element.inert = false;
    });
    if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
        lastFocusedElement.focus();
    }
}

/**
 * Closes the dialog or menu on Escape and contains keyboard focus within the dialog.
 * @param {KeyboardEvent} event The keyboard event.
 */
function handleGlobalKeydown(event) {
    if (callbackModal.getAttribute("aria-hidden") === "false") {
        if (event.key === "Escape") {
            closeCallbackModal();
            return;
        }

        if (event.key === "Tab") {
            trapModalFocus(event);
        }
        return;
    }

    if (event.key === "Escape" && menuToggle.getAttribute("aria-expanded") === "true") {
        closeNavigation();
        menuToggle.focus();
    }
}

/**
 * Keeps keyboard focus within the visible contact dialog.
 * @param {KeyboardEvent} event The Tab key event.
 */
function trapModalFocus(event) {
    const focusableElements = callbackModal.querySelectorAll(
        'button:not([disabled]), input:not([disabled]):not([tabindex="-1"]), textarea:not([disabled]), a[href]'
    );
    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement.focus();
    } else if (!event.shiftKey && document.activeElement === lastElement) {
        event.preventDefault();
        firstElement.focus();
    }
}

/**
 * Validates and sends an enquiry to the existing contact API, reporting delivery failures explicitly.
 * @param {SubmitEvent} event The contact form submission event.
 */
function onSubmitContactDetail(event) {
    event.preventDefault();
    callbackStatus.textContent = "";

    if (!callbackForm.reportValidity()) {
        return;
    }

    const submitButton = callbackForm.querySelector('button[type="submit"]');
    const formData = new FormData(callbackForm);
    const requestBody = Object.fromEntries(formData.entries());

    submitButton.disabled = true;
    callbackStatus.textContent = "Sending your enquiry…";

    fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(requestBody)
    })
        .then(async function (response) {
            const result = await response.json();
            if (!response.ok) {
                const validationMessage = result.errors ? Object.values(result.errors).flat().join(" ") : "";
                throw new Error(result.detail || result.message || validationMessage ||
                    (response.status === 429 ? "Too many enquiries. Please try again in 15 minutes or contact us directly." :
                        "We could not send your enquiry. Please try again or contact us directly."));
            }

            callbackStatus.textContent = result.message;
            callbackForm.reset();
        })
        .catch(function (error) {
            callbackStatus.textContent = error.message || "We could not connect to the email service. Please try again later.";
        })
        .finally(function () {
            submitButton.disabled = false;
        });
}
